15→/*
16→Store for a composable list box with (up to) a single selected item state.
17→*/
18→
19→/** Unique key of an item. */
20→export type ItemKey = string;
21→/** Definition of a registered item. */
22→export type ItemDef = {
23→  itemRef: React.RefObject<null | HTMLElement>,
24→  isContentItem: boolean, // Whether this counts as "content" (so not: headers, sticky actions)
25→};
26→export type ItemMap = Map<ItemKey, ItemDef>;
27→export type ItemWithKey = ItemDef & { itemKey: ItemKey };
