47→export type ListBoxState = {
48→  /**
49→   * Used to track the items that have been rendered. Note: this property is internal only, it should not be accessed
50→   * by consumers. The `Map` is mutated in place for performance, since there may be a lot of items. On initial render,
51→   * we get N registrations, an immutable update taking O(N) would result in O(N^2) updates which is not acceptable.
52→   */
53→  _internalItemsRegistry: ItemMap,
54→  
55→  /**
56→   * Keep track of the items count. Cannot be derived from `_internalItemsRegistry`, because it is mutable and so does
57→   * not trigger updates.
58→   */
59→  _internalItemsCount: number,
