 5→// Note: use the `dedupe` variant so that the consumer of a component can overwrite classes from the component using
 6→// `<MyComponent className={{ foo: false }}/>`
 7→import classNamesDedupe from 'classnames/dedupe';
 8→import type { Argument as ClassNameArgument, ArgumentArray } from 'classnames';
 9→
10→
11→export type { ClassNameArgument };
12→
13→export const isClassNameArgument = (arg: unknown): arg is ClassNameArgument => {
14→  // Note: `classNames` accepts anything at the moment, including null, undefined, functions (which are ignored), etc.
15→  return true;
16→};
17→
18→export const classNames = (...args: ArgumentArray): string => {
19→  const className = classNamesDedupe(...args);
20→  
21→  if (import.meta.env.MODE === 'development' && className.split(' ').includes('undefined')) {
22→    console.warn(`Found 'undefined' in class names list: '${className}'`);
23→  }
24→  
25→  return className;
26→};
27→
28→// Version of `React.ComponentProps` that supports `classnames` syntax for the `className` attribute. So that
29→// components can take class names not just of type string, but any valid classnames `Argument`, e.g.:
30→//   `<MyComponent className={['example1', { example2: condition() }]}/>`
31→export type ComponentProps<T extends React.ElementType> =
32→  Omit<React.ComponentProps<T>, 'className'> & {
33→    className?: undefined | ClassNameArgument,
34→  };
