 5→import * as React from 'react';
 6→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 7→
 8→import cl from './Link.module.scss';
 9→import { mergeCallbacks } from '../../../util/reactUtil.ts';
10→
11→
12→export { cl as LinkClassNames };
13→
14→export type LinkProps = React.PropsWithChildren<ComponentProps<'a'> & {
15→  /** Whether this component should be unstyled. */
16→  unstyled?: undefined | boolean,
17→  
18→  /* Size of the link */
19→  size?: 'small' | 'medium',
20→  
21→  /**
22→   * The label of the link. Additional UI elements may be added, e.g. a loading indicator. If full control over
23→   * the link content is desired, use `children` instead, this overrides the `label`.
24→   */
25→  label?: undefined | string,
26→  
27→  /**
28→   * Whether the link is disabled. Default: `false`.
29→   */
30→  disabled?: undefined | boolean,
31→}>;
32→
33→
34→/**
35→ * Link component.
36→ */
37→export const Link = (props: LinkProps) => {
38→  const {
39→    children,
40→    unstyled = false,
41→    size = 'medium',
42→    label,
43→    disabled = false,
44→    href,
45→    ...propsRest
46→  } = props;
47→  
48→  // Note: not really necessary anymore in modern browsers, but doesn't hurt
49→  // https://stackoverflow.com/questions/50709625/link-with-target-blank-still-vulnerable
50→  const rel = propsRest.target === '_blank' ? 'noopener noreferrer' : undefined;
51→  
52→  const handleClickDisabled = React.useCallback((event: React.MouseEvent) => {
53→    event.preventDefault();
54→  }, []);
55→  
56→  return (
57→    <a
58→      rel={rel}
59→      href={href}
60→      aria-disabled={disabled ? true : undefined}
61→      {...propsRest}
62→      className={cx(
63→        'bk',
64→        cl['bk-link'],
65→        { [cl['bk-link--unstyled']]: unstyled },
66→        { [cl['bk-link--disabled']]: disabled },
67→        { [cl['bk-link--small']]: size === 'small' },
68→        props.className,
69→      )}
70→      onClick={mergeCallbacks([propsRest.onClick, disabled ? handleClickDisabled : undefined])}
71→    >
72→      {children ?? label}
73→    </a>
74→  );
75→};
