54→export const Checkbox = Object.assign(
55→  (props: CheckboxProps) => {
56→    const { unstyled = false, onUpdate, ...propsRest } = props;
57→    
58→    const handleChange = React.useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
