 50→
 51→type SegmentedControlButtonProps = ComponentProps<typeof Button> & {
 52→  /** Whether this component should be unstyled. */
 53→  unstyled?: undefined | boolean,
 54→  
 55→  /** The unique key of this button within the segmented control. */
 56→  buttonKey: ButtonKey,
 57→};
 58→const SegmentedControlButton = (props: SegmentedControlButtonProps) => {
 59→  const { unstyled, buttonKey, ...propsRest } = props;
 60→  
 61→  const buttonRef = React.useRef<React.ComponentRef<typeof Button>>(null);
 62→  const buttonDef = React.useMemo<ButtonDef>(() => ({ buttonKey, buttonRef }), [buttonKey]);
 63→  
 64→  const context = useSegmentedControlContext(buttonDef);
 65→  const isSelected = context.selectedButton === buttonKey;
 66→  
 67→  return (
 68→    <Button
 69→      unstyled
 70→      role="radio"
 71→      aria-checked={isSelected}
 72→      tabIndex={isSelected ? 0 : -1} // "Roving" tab index
 73→      {...propsRest}
 74→      ref={mergeRefs(buttonRef, propsRest.ref)}
 75→      className={cx(
 76→        { [cl['bk-segmented-control__button']]: !unstyled },
 77→        propsRest.className,
 78→      )}
 79→      onPress={() => {
 80→        propsRest.onPress?.();
 81→        context.selectButton(buttonKey);
 82→      }}
 83→      disabled={context.disabled || propsRest.disabled}
 84→    />
 85→  );
 86→};
