15→/*
16→Store for a composable list box with (up to) a single selected item state.
17→*/
18→
19→/** Unique key of an item. */
20→export type ItemKey = string;
21→/** Definition of a registered item. */
22→export type ItemDef = {
23→  itemRef: React.RefObject<null | HTMLElement>,
24→  isContentItem: boolean, // Whether this counts as "content" (so not: headers, sticky actions)
25→};
26→export type ItemMap = Map<ItemKey, ItemDef>;
27→export type ItemWithKey = ItemDef & { itemKey: ItemKey };
28→
29→export type ItemDetails = { itemKey: ItemKey, label: string };
30→
31→/**
32→ * The minimal subtype of `Array<ItemKey>` that we need to be able to render a virtualized list. We keep it minimal
33→ * so that the consumer may compute this information dynamically rather than storing it all in memory. For best
34→ * performance, each of the defined operations should be computable in (or close to) O(1), this may require some
35→ * caching (e.g. maintaining a reverse lookup table for `indexOf`).
36→ */
37→export type VirtualItemKeys = Pick<ReadonlyArray<ItemKey>, 'length' | 'at' | 'indexOf'>;
38→export const VirtualItemKeysUtil = {
39→  /** Find the index of the given `itemKey`, or `null` if not found in the list. */
40→  indexForItemKey: (virtualItemKeys: VirtualItemKeys, itemKey: ItemKey): null | number => {
41→    const index = virtualItemKeys.indexOf(itemKey);
42→    return index >= 0 ? index : null;
43→  },
44→};
45→
46→
47→export type ListBoxState = {
48→  /**
49→   * Used to track the items that have been rendered. Note: this property is internal only, it should not be accessed
50→   * by consumers. The `Map` is mutated in place for performance, since there may be a lot of items. On initial render,
51→   * we get N registrations, an immutable update taking O(N) would result in O(N^2) updates which is not acceptable.
52→   */
53→  _internalItemsRegistry: ItemMap,
54→  
55→  /**
56→   * Keep track of the items count. Cannot be derived from `_internalItemsRegistry`, because it is mutable and so does
57→   * not trigger updates.
58→   */
59→  _internalItemsCount: number,
